package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaUzDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus (Ruku va Sujud)", "(Alloh) pok, muqaddas, farishtalarning va ruhning Robbidir.", "Ruku va sajdada.", "Rasululloh ﷺ buni ruku va sajdada o'qidilar."),
        "dua_sujood_dhanbi_kullah" to DuaText("Sujudda: Barcha gunohlarimni kechir", "Allohim, mening barcha gunohlarimni – kichik va katta, birinchi va oxirgi, oshkoru va yashirin gunohlarimni kechir.", "Sujudda.", "Sajda duolar ijobat qilinadigan joydir."),
        "dua_sujood_ridaka" to DuaText("O'z roziligingdan panoh top", "Allohim, g'azabingdan rizoligingdan, azobingdan mag'firatingdan panoh tilayman va Sendan panoh tilayman. Men Seni to'liq ulug'lay olmayman; O'zingni ulug'laganingdeksan.", "Sujudda — Oisha (RA) Rasululloh sollallohu alayhi vasallam ﷺ aytganlarini eshitdilar.", "Payg'ambarning sajda duolari ﷺ."),
        "dua_tashahhud" to DuaText("Tashahhud (at-Tahiyot)", "Barcha og'zaki, jismoniy va moliyaviy ibodatlar Alloh uchundir. Assalomu alaykum, ey payg‘ambar, Allohning rahmati va barakotlari. Bizga va Allohning solih bandalariga salom bo'lsin. Guvohlik beramanki, Allohdan boshqa hech kim ibodat qilinishga loyiq emas va Muhammad ﷺ Uning bandasi va rasuli ekanligiga guvohlik beraman.", "Har bir majlisda — Abdulloh ibn Mas'ud rivoyati (RA) (hanafiy mazhabi).", "Payg'ambar ﷺ uni Qur'on surasi kabi o'rgatgan."),
        "dua_sajdah_tilawah" to DuaText("Qiroat sajdasi", "Mening yuzim uni yaratgan va qudrati va qudrati bilan uning eshitish va ko'rish qobiliyatini yaratgan zotga sajda qildi.", "Qiroat sajdasida.", "Payg'ambarimiz ﷺ kechasi qiroat sajdasida aytdilar."),
        "dua_after_witr" to DuaText("Vitrdan keyin", "Muqaddas Podshohga shon-sharaflar bo'lsin.", "Vitr salomidan keyin uch marta, uchinchi marta ovozni ko'tarish.", "Rasululloh ﷺ vitrdan keyin aytdilar."),
        "dua_tahajjud_nur" to DuaText("Tahajjud ochilish duosi", "Allohim, senga hamd bo'lsin. Osmonlar, yer va ulardagi barcha narsalarning Parvardigori Sensan. Hamd Senga xosdir. Sen osmonlar, yer va ulardagi hamma narsaning nurisan. Hamd Senga xosdir. Sen Haqsan, Va'dang haq, Sen bilan uchrashuv haqdir, So'zing haqdir, Jannat haqdir, Do'zax haqdir, Payg'ambarlar haqdir, Muhammad ﷺ haqdir, Qiyomat ham haqdir.", "Xufton namozini (tahajjud) boshlaganda (duoning ochilish qismi).", "Nabiy sallallohu alayhi vasallam ﷺ tahajjudga chiqqanlarida buni o'qidilar (to'liq duo Buxoriyda keltirilgan)."),
        "dua_rabba_jibrail" to DuaText("Bahsli masalalarda menga rahbarlik qiling", "Ey Jabroil, Mikoil va Isrofilning Parvardigori, osmonlaru erni yaratuvchisi, gʻaybni ham, oshkorani ham bilguvchi Allohim! Sen bandalaring orasida ixtilof qilgan narsalarida hukm qilursan. Meni izn ila ixtilof qilingan narsada haqga hidoyat qilgin. Albatta, Sen kimni xohlasang, to'g'ri yo'lga hidoyat qilursan.", "Tahajjud boshlanishida - ixtilofda haqiqatga yo'l ko'rsatish uchun.", "Payg'ambarimiz ﷺ xufton namozini shu duo bilan boshlaganlar."),
        "dua_going_to_mosque_nur" to DuaText("Masjidga borish (Nur duosi)", "Allohim, qalbimga nur, ko'zlarimga nur, qulog'imga nur, o'ngimga nur, chapimga nur, tepamga nur, pastimga nur, oldimga nur, orqamga nur va menga nur ber.", "Bomdod namoziga masjidga ketayotganda.", "Payg'ambar ﷺ namozga chiqayotganda buni o'qigan."),
        "dua_waswasa_salah" to DuaText("Namoz vaqtida vasvasa (Xinzab)", "Men la’nati shaytondan Allohdan panoh tilayman.", "Namoz vaqtida shaytonning shivirlari kelsa, panoh so'rang va uch marta chap tomonga engil tupuring.", "Usmon ibn Abil-Os (RA) shunday qildilar va pichirlashlar ketdi."),
        "dua_alimal_ghayb" to DuaText("G'aybni bilguvchi", "Ey gʻaybni ham, oshkorani ham bilguvchi, osmonlaru erni yaratuvchisi, barcha narsaning Robbi va hukmdori boʻlgan Alloh! Sendan o'zga iloh yo'qligiga guvohlik beraman. Nafsimning yomonligidan, shaytonning yomonligidan va uning shirkidan panoh tilayman.", "Ertalab, kechqurun va uyqudan oldin - Payg'ambar ﷺ Abu Bakrga (RA) o'rgatgan.", "Nafs va shaytonning yomonligidan asrash."),
        "dua_fitratil_islam" to DuaText("Islomning fitrati haqida", "Tongga Islom fitratiga, ixlos kalomiga, Payg‘ambarimiz Muhammadning diniga ﷺ va to‘g‘ri va musulmon bo‘lgan, mushriklardan bo‘lmagan otamiz Ibrohim (AS) yo‘liga kirdik.", "Ertalabda.", "Har tongda iymonni yangilash."),
        "dua_amsayna_fitrah" to DuaText("Islomning Fitra kechasi", "Shomga Islomning fitrati, ixlos kalomi, payg'ambarimiz Muhammad alayhissalomning dini ﷺ va to'g'ri va musulmon bo'lgan, mushriklardan bo'lmagan Ibrohim otamiz (AS) yo'li bilan kirdik.", "Kechqurun.", "Har oqshom insonning iymonini yangilash."),
        "dua_tahleel_10_fajr" to DuaText("Bomdod va shomdan keyin o'n tahlil", "Allohdan boshqa hech kim ibodat qilinishga loyiq emas, yolg'iz, sherigi yo'q. Mulk Uniki va hamd Unikidir. U tiriltirur va o'ldiradi va U har bir narsaga qodirdir.", "Bomdoddan keyin (va shomdan keyin) o‘tirishdan yoki gapirishdan oldin o‘n marta.", "O'nta yaxshilik, o'nta gunoh o'chiriladi, o'n martaba ko'tariladi va kun bo'yi shaytondan himoya qilinadi."),
        "dua_la_hawla_kanz" to DuaText("Jannat xazinasi", "Allohdan boshqa hech qanday kuch va kuch yo'q.", "Ko'pincha, har doim.", "U jannat xazinalaridan biridir."),
        "dua_four_beloved_words" to DuaText("Eng sevimli to'rtta so'z", "Alloh pokdir, barcha hamd Allohga xosdir, Allohdan boshqa hech kim ibodat qilinishga loyiq emas va Alloh eng buyukdir.", "Allohga eng sevimli so'zlar.", "Ular Payg'ambar ﷺ uchun quyosh chiqadigan har bir narsadan ham sevimliroqdirlar."),
        "dua_two_light_words" to DuaText("Ikki so'z tilga nur", "Alloh taologa pok va hamdu sanolar bo'lsin. Ulug' zot Allohga pok bo'lsin.", "Tilda yengil, tarozida og'ir.", "Rahmonga mahbub, tilga yengil, taroziga og'ir. (Al-Buxoriyning oxirgi hadisi)"),
        "dua_ya_dhal_jalal" to DuaText("Ya Zhal-Jaloli val-Ikrom", "Ey azizlik va ikrom sohibi!", "Duoda uni ushlab turing - Payg'ambarning ﷺ ko'rsatmasi.", "Rasululloh ﷺ dedilar: “Yo Zhal-Jaloli val-Ikrom”ni mahkam tutinglar."),
        "dua_sleep_wadatu_janbi" to DuaText("Sening noming bilan yotdim", "Ey Robbim, Sening noming bilan yonboshladim va Sening noming bilan turaman. Agar mening jonimni olsang, unga rahm qil, agar uni qo‘yib yuborsang, solih bandalaringni himoya qilganingdek, uni asra.", "To'shakda changni artib, yotgandan keyin.", "Uxlashdan oldin jonni Allohga topshirish."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Siz mening qalbimni yaratdingiz", "Allohim, ruhimni yaratgansan, uni olasan. Uning o'limi ham, hayoti ham Sennikidir. Agar uni tirik tutsang, himoya qil, agar o‘limiga sababchi bo‘lsang, kechir. Allohim, sendan omonlik tilayman.", "Uxlashdan oldin — Ibn Umar rivoyati (RA).", "Payg'ambar ﷺ yotishdan oldin buni aytishni buyurgan."),
        "dua_sleep_atamana" to DuaText("Uxlashdan oldin minnatdorchilik", "Bizni yedirgan, ichdirgan, kifoya qilgan va panoh bergan Allohga hamdlar bo'lsin. Qanchadan-qancha, ularga yetadigan yoki boshpana beradigan hech kim yo'q.", "Uyquga ketayotganda.", "Payg'ambarimiz ﷺ uxlayotganlarida aytdilar."),
        "dua_sleep_rabbas_samawat" to DuaText("Osmonlar Rabbiysi - Qarzimizni to'lang", "Ey osmonlar, yer va aziz arshning Robbi, bizning Robbimiz va barcha narsaning Parvardigori, urug‘ va xurmoni parchalovchi, Tavrot, Injil va Furqonni nozil qiluvchi Alloh! Peshonasidan ushlab turgan har bir narsaning yomonligidan Sendan panoh tilayman. Allohim, Sen birinchisan, Sendan oldin hech narsa yo'q; Sen oxirgisan, Sendan keyin hech narsa yo'q; Sen zohirsan, Sendan ustingizda hech narsa yo'q. Sen Yashirinsan, Sendan sir yo'q. Bizning qarzimizni to'la va bizni qashshoqlikdan xalos qil.", "Uxlashdan oldin, o'ng tomonda yotish - Fotimaga o'rgatgan (RA).", "Qarz va qiyinchilikdan qutulish uchun duo."),
        "dua_sleep_fear" to DuaText("Uyqudagi qo'rquv yoki bezovtalik", "Allohning g‘azabi va azobidan, bandalarining yomonligidan, shaytonlarning vasvasasidan va ularning menga kelishidan Allohning mukammal so‘zlari bilan panoh so‘rayman.", "Uyquda qo'rquv yoki bezovtalikni his qilganda.", "Shunday qilsa, bu narsa unga zarar keltirmaydi."),
        "dua_waking_afani" to DuaText("Uyg'onish: U mening ruhimni tikladi", "Badanimga sog'lik ato etgan, ruhimni menga qaytargan va Uni zikr qilishimga imkon bergan Allohga hamdlar bo'lsin.", "Uyg'onganda.", "Yangi tong uchun rahmat."),
        "dua_allahu_rabbi" to DuaText("Alloh, Alloh mening Robbimdir", "Alloh, Alloh mening Robbimdir. Men Unga hech narsani sherik qilmayman.", "Qayg'u yoki qayg'uda - Payg'ambar ﷺ Asmo binti Umaysga o'rgatgan (RA).", "Qiyinchilikda tavhidni mahkam ushlash."),
        "dua_rahmataka_arju" to DuaText("Sizning mehringizdan umid qilaman", "Allohim, men umid qilgan rahmatingdandir, meni ko'z ochib yumguncha ham o'z holimga tashlab qo'yma va barcha ishlarimni isloh qil. Sendan boshqa iloh yo'q.", "Qiyinchilikdagining duosi (Davotul makrub).", "Payg'ambar ﷺ uni musibatdagining duosi deb atagan."),
        "dua_against_enemy_ahzab" to DuaText("Dushman qo'shinlariga qarshi", "Ey Kitobni nozil qilguvchi, tez hisob qiluvchi Alloh! Konfederatsiyalarni mag'lub qiling. Allohim, ularni mag'lub et va ularni silkit.", "Dushmanga qarshi - Konfederatsiyalar jangining duosi.", "Payg'ambarning dushmanga qarshi ﷺ duosi."),
        "dua_anta_adudi" to DuaText("Siz mening tayanchimsiz", "Allohim, sen mening tayanchim va yordamchimsan. Sen bilan reja qilaman, Sen bilan oldinga boraman va Sen bilan jang qilaman.", "Musobaqa yoki katta sinovdan oldin.", "Rasululloh ﷺ jangda shunday deganlar."),
        "dua_ikfinihim" to DuaText("Ularga qarshi bo'lsam kifoya", "Allohim, sen xohlaganingcha ularga qarshi menga kifoya qil.", "Zolimlarning yovuzligiga qarshi — “Xandaq ahli” qissasidagi bola duosi.", "Alloh taolo bolani zolimlardan qutqardi."),
        "dua_qadarullah" to DuaText("Yomon narsa yuz berganda", "Bu Allohning hukmi bo'lib, O'zi xohlaganini qildi.", "Noxush narsa yuz berganda, \"agar bo'lsa\" deyish o'rniga.", "\"Agar\" shaytonga eshikni ochadi."),
        "dua_ala_kulli_hal" to DuaText("Har bir vaziyatda maqtov", "Har qanday holatda ham Allohga hamd bo'lsin.", "Yoqtirmagan narsa sodir bo'lganda.", "Rasululloh ﷺ o'zlari yoqtirmagan narsaga duch kelganlarida shunday dedilar."),
        "dua_dogs_barking" to DuaText("Kechasi itlarning huriyotganini eshitish", "Men la’nati shaytondan Allohdan panoh tilayman.", "Kechasi itlarning hurishini yoki eshakning baqirayotganini eshitganda.", "Ular siz ko'rmagan narsani ko'radilar."),
        "dua_leaving_home_adilla" to DuaText("Adashishdan panoh", "Allohim, adashib qolishimdan yoki zalolatga tushib qolishimdan, sirpanib qolishimdan yoki sirpanib qolishimdan, zulm qilishimdan yoki zulm qilishimdan, ahmoqlik qilishimdan yoki nodonlik qilishimdan Sendan panoh tilayman.", "Uydan chiqayotganda — Ummu Salama rivoyati (RA).", "Payg‘ambarimiz ﷺ uylaridan chiqqanlarida buni o‘qirdilar."),
        "dua_ascending_descending" to DuaText("Yuqoriga chiqish va pastga tushish", "Alloh buyukdir (ko'tarilayotganda). — Alloh taologa pok bo'lsin (tushganda).", "Sayohatda ko'tarilayotganda \"Allohu akbar\", tushayotganda \"Subhanalloh\" deng.", "Sahobalarning amali (RA) sayohat paytida."),
        "dua_traveller_sahar" to DuaText("Sayohatchining tong otguncha duosi", "Bir tinglovchi bizning Allohga hamdu sanolarimizni va Uning bizga bo'lgan ne'matlarini eshitdi (va aytdi). Ey Robbimiz, bizga hamroh bo'l va bizga ne'matingni ato etgin - (buni aytaman) Allohdan do'zaxdan panoh tilayman.", "Sayohatda, tong otguncha.", "Payg'ambarimiz ﷺ tong otishidan oldin sayohat qilganlarida aytdilar."),
        "dua_zawwadakallah" to DuaText("Sayohatchiga: Alloh taqvoni bersin", "Alloh taolo safaringizga taqvo bersin, gunohlaringizni kechirsin va qayerda bo'lsangiz ham yaxshilikni oson qilsin.", "Sayohatchi bilan xayrlashayotganda.", "Payg'ambarimiz (sollallohu alayhi vasallam) ﷺ bu duoni safarga chiqqan kishiga aytganlar."),
        "dua_traveller_to_resident" to DuaText("Orqada qolganlarga sayohatchi", "Sizni omonatlar zoe bo'lmaydigan Allohga topshirdim.", "Sayohatchi oilasi bilan xayrlashayotganda aytgan.", "Oila xavfsizligini Ollohga topshirish."),
        "dua_entering_village" to DuaText("Shahar yoki qishloqqa kirish", "Ey yetti osmon va ular soya qiladigan narsalarning Parvardigori, yetti erning va ular ko‘targan narsalarning Robbisi, shaytonlarning Robbisi va ular yo‘ldan ozdiradigan narsalarning Robbisi, shamollar va ular sochib yuboradigan narsalarning Robbisi Allohim! Sendan bu shaharning va uning ahlining yaxshiligini so‘raymiz va uning yomonligidan, ahlining yomonligidan va undagi narsalarning yomonligidan Sendan panoh tilaymiz.", "Shahar yoki shaharga kirishdan oldin.", "Payg'ambarimiz ﷺ har bir shaharga kirmoqchi bo'lganlarida buni o'qidilar."),
        "dua_vehicle_stumbles" to DuaText("Avtomobil qoqilib ketganda", "Alloh nomi bilan.", "“Shayton halok bo‘lsin” deyish o‘rniga tog‘ yoki mashina sirpanib qolsa yoki qoqilib qolsa.", "Bismilloh deyish shaytonni pashshadek kichraytiradi."),
        "dua_ajz_kasal_haram" to DuaText("Zaiflik va qarilikdan panoh", "Allohim, ojizlik va dangasalikdan, qo‘rqoqlik va qarilikdan, hayot va mamot sinovlaridan, qabr azobidan panoh tilayman.", "Kundalik keng qamrovli boshpana duosi.", "Rasululloh ﷺ tez-tez qilgan duo."),
    )
}
